import { 
  MeshBasicNodeMaterial 
} from 'three/webgpu';
import { 
  uv, 
  vec2, 
  mix 
} from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector4, Color } = ctx.THREE;
  const container = new Group();

  // 1. COLORS & VISUAL TOKENS
  const colors = {
    ink: new Color(config.colors?.ink ?? '#16161d'),
    paper: new Color(config.colors?.paper ?? '#e8ecf2'),
    accent: new Color(config.colors?.accent ?? '#ff2a38'),
    surface: new Color(config.colors?.surface ?? '#0b0b10')
  };

  // 2. BACKDROP / STAGE PLANE (Avoiding void, complying with W-PCP §9 STAGE rule)
  // We construct an engineered gradient backdrop stage matching Nova Atelier theme
  const backdropGeo = new PlaneGeometry(7.2, 5.8);
  const backdropMat = new MeshBasicNodeMaterial({ depthWrite: false });

  // Custom TSL gradient (vertical ink to near-black surface transition with subtle red accent leakage)
  const vUv = uv();
  const gradColor = mix(
    colors.surface,
    colors.ink,
    vUv.y
  );
  backdropMat.colorNode = gradColor;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.1);
  container.add(backdrop);

  // 3. MAIN HERO PLANE (Plane Render Mode)
  // Feature Card size 5.2 x 3.2 to optimally fill the hub frame
  const cardGeo = new PlaneGeometry(5.2, 3.2);
  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.0 // starts hidden for entrance transition
  });

  // Handle Texture Atlased mapping or full load
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.colorSpace = ctx.THREE.SRGBColorSpace;
      // Atlas source rect handling
      // Region: 0, 0, 512, 320
      texture.repeat.set(1.0, 1.0);
      texture.offset.set(0.0, 0.0);
      cardMat.map = texture;
      cardMat.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading feature image:", err);
    });
  }

  const cardMesh = new Mesh(cardGeo, cardMat);
  container.add(cardMesh);

  // 4. DESIGN ELEMENT: MACHINED RED ACCENT LINE (PCP §9 Palette accent <= 10%)
  const accentLineGeo = new PlaneGeometry(5.2, 0.04);
  const accentLineMat = new MeshBasicNodeMaterial({ color: colors.accent });
  const accentLine = new Mesh(accentLineGeo, accentLineMat);
  accentLine.position.set(0, -1.58, 0.01);
  container.add(accentLine);

  // 5. MOTION WITH WEIGHT (GSAP Entrance Animation)
  // Settle overshoot / weighted-settle transition
  const tl = gsap.timeline();
  tl.fromTo(
    cardMesh.position,
    { y: -0.4, z: -0.2 },
    { y: 0.0, z: 0.0, duration: 1.1, ease: 'power4.out' }
  );
  tl.fromTo(
    cardMat,
    { opacity: 0.0 },
    { opacity: 1.0, duration: 0.8, ease: 'power2.out' },
    '<'
  );
  tl.fromTo(
    accentLine.scale,
    { x: 0 },
    { x: 1, duration: 1.2, ease: 'power3.out' },
    '-=0.6'
  );

  // Clean-up requirement implementation
  container.userData = {
    handlers: {},
    cleanup: () => {
      if (tl) tl.kill();
      cardGeo.dispose();
      cardMat.dispose();
      backdropGeo.dispose();
      backdropMat.dispose();
      accentLineGeo.dispose();
      accentLineMat.dispose();
    }
  };

  return container;
}
